return function(source,filter,less) local m={source=source,indices={}};function m:refresh() local v={};for i=1,self.source:count() do if not filter or filter(self.source:get(i)) then v[#v+1]=i end end;if less then table.sort(v,function(a,b)return less(self.source:get(a),self.source:get(b)) end) end;self.indices=v end;function m:count() return #self.indices end;function m:get(i,j) return self.source:get(self.indices[i],j) end;m:refresh();return m end
